pub struct Quadtree {
    pub root: Option<Box<QuadtreeNode>>,
    pub key_free: Option<fn(*mut std::ffi::c_void)>,
    pub length: u32,
}

pub fn quadtree_bounds_extend(bounds: &mut QuadtreeBounds, x: f64, y: f64) {
    if let Some(nw) = bounds.nw.as_mut() {
        nw.x = f64::min(x, nw.x);
        nw.y = f64::max(y, nw.y);
    }
    if let Some(se) = bounds.se.as_mut() {
        se.x = f64::max(x, se.x);
        se.y = f64::min(y, se.y);
    }
    if let (Some(nw), Some(se)) = (bounds.nw.as_ref(), bounds.se.as_ref()) {
        bounds.width = (nw.x - se.x).abs();
        bounds.height = (nw.y - se.y).abs();
    }
}

pub fn quadtree_node_new() -> Option<Box<QuadtreeNode>> {
    Some(Box::new(QuadtreeNode {
        ne: None,
        nw: None,
        se: None,
        sw: None,
        bounds: None,
        point: None,
        key: None,
    }))
}

pub fn quadtree_node_isleaf(node: &QuadtreeNode) -> bool {
    node.point.is_some()
}

pub fn quadtree_walk(
    root: &mut QuadtreeNode,
    descent: &mut dyn FnMut(&mut QuadtreeNode),
    ascent: &mut dyn FnMut(&mut QuadtreeNode),
) {
    descent(root);
    if let Some(ref mut nw) = root.nw {
        quadtree_walk(nw, descent, ascent);
    }
    if let Some(ref mut ne) = root.ne {
        quadtree_walk(ne, descent, ascent);
    }
    if let Some(ref mut sw) = root.sw {
        quadtree_walk(sw, descent, ascent);
    }
    if let Some(ref mut se) = root.se {
        quadtree_walk(se, descent, ascent);
    }
    ascent(root);
}

pub fn node_contains(outer: &QuadtreeNode, it: &QuadtreePoint) -> bool {
    if let Some(bounds) = &outer.bounds {
        if let (Some(nw), Some(se)) = (&bounds.nw, &bounds.se) {
            return nw.x < it.x && nw.y > it.y && se.x > it.x && se.y < it.y;
        }
    }
    false
}

pub fn quadtree_node_with_bounds(minx: f64, miny: f64, maxx: f64, maxy: f64) -> Option<Box<QuadtreeNode>> {
    let mut node = quadtree_node_new()?;
    let mut bounds = quadtree_bounds_new()?;
    quadtree_bounds_extend(&mut bounds, maxx, maxy);
    quadtree_bounds_extend(&mut bounds, minx, miny);
    node.bounds = Some(Box::new(bounds));
    Some(node)
}

pub fn quadtree_node_reset(node: &mut QuadtreeNode, key_free: fn(*mut std::ffi::c_void)) {
    if let Some(key) = node.key.take() {
        key_free(Box::into_raw(key) as *mut std::ffi::c_void);
    }
}

pub fn get_quadrant<'a>(root: &'a QuadtreeNode, point: &QuadtreePoint) -> Option<&'a QuadtreeNode> {
    if let Some(ref nw) = root.nw {
        if node_contains(nw, point) {
            return Some(nw);
        }
    }
    if let Some(ref ne) = root.ne {
        if node_contains(ne, point) {
            return Some(ne);
        }
    }
    if let Some(ref sw) = root.sw {
        if node_contains(sw, point) {
            return Some(sw);
        }
    }
    if let Some(ref se) = root.se {
        if node_contains(se, point) {
            return Some(se);
        }
    }
    None
}

pub fn quadtree_new(minx: f64, miny: f64, maxx: f64, maxy: f64) -> Option<Box<Quadtree>> {
    let mut tree = Box::new(Quadtree {
        root: None,
        key_free: None,
        length: 0,
    });
    tree.root = quadtree_node_with_bounds(minx, miny, maxx, maxy);
    if tree.root.is_none() {
        return None;
    }
    Some(tree)
}

pub fn find(node: &QuadtreeNode, x: f64, y: f64) -> Option<&QuadtreePoint> {
    if quadtree_node_isleaf(node) {
        if let Some(point) = &node.point {
            if point.x == x && point.y == y {
                return Some(point);
            }
        }
    } else {
        let test = QuadtreePoint { x, y };
        if let Some(quadrant) = get_quadrant(node, &test) {
            return find(quadrant, x, y);
        }
    }
    None
}

